export function tareasCatalogo(normaId, modelo) {
  return (CATALOGO_TAREAS[normaId]?.[modelo]) || [];
}

// Catálogo aplanado para el editor (modo demo siembra la tabla con esto)
export function catalogoFilas() {
  const out = [];
  let i = 0;
  for (const norma of Object.keys(CATALOGO_TAREAS)) {
    for (const modelo of Object.keys(CATALOGO_TAREAS[norma])) {
      let orden = 0;
      for (const t of CATALOGO_TAREAS[norma][modelo]) {
        i += 1; orden += 1;
        out.push({
          id: `cat_${i}`, norma_id: norma, modelo,
          proceso: t.proceso, subproceso: t.subproceso,
          titulo: `${t.proceso} - ${t.subproceso}`,
          horas_base: t.horas, reduccion_pct: 0, descripcion: t.descripcion || '', orden,
        });
      }
    }
  }
  return out;
}
